import html,json
from pathlib import Path
from .core import build_kit,SUPPORTS
CSS='''*{box-sizing:border-box}body{margin:0;background:#f6f3ed;color:#263950;font:16px/1.6 system-ui}main{max-width:1140px;margin:auto;padding:34px 24px}header{padding:34px;border-radius:22px;background:#173d52;color:white}h1{font-size:clamp(30px,5vw,50px);line-height:1.1;margin:15px 0}h2{font-size:25px}h3{font-size:18px}.eyebrow{letter-spacing:.12em;color:#bfe4d6;font-size:13px}.controls{display:flex;flex-wrap:wrap;gap:18px;background:white;padding:20px;border-radius:15px;margin:24px 0}label{font-weight:650}select,button{font:inherit;padding:10px;border-radius:8px;border:1px solid #99adba;background:white;color:#20384c;cursor:pointer;max-width:100%}select{display:block;margin-top:6px}button.primary{background:#1c6a62;color:white}.card,.panel{background:white;border:1px solid #e0e3dc;border-radius:14px;padding:22px;margin:14px 0}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.word{margin:0}.word strong{font-size:18px;display:block}.cue{font-size:32px}.muted{color:#586b79;font-size:14px}.notice{background:#fff0cf;padding:16px;border-radius:12px}.pill{background:#dff0e6;color:#205747;border-radius:20px;padding:4px 11px;font-size:13px}.line{display:flex;gap:15px;flex-wrap:wrap;align-items:center;justify-content:space-between}table{width:100%;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid #dfe5e3;text-align:left;vertical-align:top}.table{overflow:auto}.write{border-bottom:1px solid #adb8be;min-height:48px}summary{cursor:pointer}a{color:#156d61}.actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:16px}footer{margin:30px 0;color:#596e7b}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#edf4ef;padding:15px;font-size:13px}@media(max-width:700px){.grid{grid-template-columns:1fr 1fr}main{padding:20px 14px}header{padding:24px}.controls>*{width:100%}}@media print{body{background:white}header{background:white;color:#222;padding:0}main{max-width:none;padding:0}.controls,.actions,.teacher,.answers,.video,.notice,footer{display:none!important}.panel{border:0;padding:0}.grid{grid-template-columns:repeat(3,1fr)}.word{break-inside:avoid}button{display:none}.eyebrow{color:#222}}@page{size:A4;margin:12mm}@media print{body{font-size:12px;line-height:1.4}h1{font-size:26px;margin:8px 0}h2{font-size:18px;margin:10px 0}h3{font-size:14px}p{margin:8px 0}.panel{margin:10px 0}.card.word{padding:10px}.word strong{font-size:14px}.cue{font-size:22px}.grid{gap:8px}.muted,.pill{font-size:11px}.write{min-height:36px}.learner{break-before:page}#models,.table,table,tr{break-inside:avoid}.table{overflow:visible}th,td{padding:7px}#voice-status{display:none}}'''

def body(kit):
 e=html.escape
 language=kit['aid_language']
 words=''.join(f'<div class="card word"><span class="cue" aria-hidden="true">{e(w["cue"])}</span><strong>{e(w["fr"])}</strong>'+ (f'<span>{e(w[language])}</span>' if language!='fr' else '')+'</div>' for w in kit['lexicon'])
 stages=''.join(f'<article class="card"><h3>{e(s["name"])} · {s["minutes"]} min</h3><p class="muted">{e(s["grouping"])}</p><p>{e(s["instructions"])}</p></article>' for s in kit['teacher']['stages'])
 criteria=''.join(f'<tr><td>{e(c["text"])}</td><td>{e(c["threshold"])}</td><td>☐ Atteint<br>☐ En cours<br>☐ Non observé</td></tr>' for c in kit['teacher']['criteria'])
 ex=kit['learner']['exercise']
 items=''.join(f'<p>{i+1}. {e(w["fr"])} → ______</p>' for i,w in enumerate(ex['items']))
 choices=''.join(f'<p>{c["letter"]}. {e(c["text"])}</p>' for c in ex['choices'])
 models=''.join('<p>'+e(m)+'</p>' for m in kit['models'])
 videos=''.join('<p><a href="'+e(v['url'],quote=True)+'" target="_blank" rel="noopener noreferrer">'+e(v['title'])+'</a></p>' for v in kit['approved_videos']) or '<p>Aucune vidéo approuvée pour cette fiche. Le cours peut fonctionner avec la lecture de l’enseignant.</p>'
 candidates=''.join('<p><a href="'+e(v['url'],quote=True)+'" target="_blank" rel="noopener noreferrer">'+e(v['title'])+'</a> — '+e(v['review_status'])+'</p>' for v in kit['video_candidates'])
 return f'''<section class="panel"><div class="line"><h2>{e(kit['title'])}</h2><span class="pill">A1 · Grade {kit['suggested_grade']} · 45 min</span></div><p><strong>Objectif :</strong> {e(kit['objective'])}</p><p class="notice">Ressource proposée, à relire et adapter par l’enseignant. Pas de validation en classe revendiquée. Les symboles sont des repères indicatifs ; utiliser des objets ou dessins explicites pour évaluer le sens.</p></section>
<section class="panel"><h2>Lexique et aide de sens</h2><div class="grid">{words}</div></section><section class="panel"><h2>Trois modèles pour parler</h2><div id="models">{models}</div><p>{e(kit['grammar'])}</p><div class="actions"><button type="button" id="speak">Écouter les modèles</button><button type="button" id="stop">Arrêter</button></div><p id="voice-status" role="status" aria-live="polite" class="muted">Lecture vocale facultative : dépend des voix françaises du navigateur. Aucun fichier audio préenregistré.</p></section>
<section class="panel learner"><h2>Ma fiche apprenant</h2><p>{e(ex['prompt'])}</p><div class="grid"><div>{items}</div><div>{choices}</div></div><p class="muted">{e(ex['note'])}</p><h3>{e(kit['learner']['task'])}</h3><div class="write">1.</div><div class="write">2.</div><div class="write">3.</div></section>
<section class="panel teacher"><h2>Fiche enseignant</h2><p><strong>Aide choisie :</strong> {e(kit['differentiation'])}</p><p>{e(kit['teacher']['resources'])}</p>{stages}</section><section class="panel"><h2>Je peux…</h2><div class="table"><table><thead><tr><th>Critère</th><th>Seuil observable</th><th>Observation</th></tr></thead><tbody>{criteria}</tbody></table></div><p>Aide utilisée : _____________________ · Prochaine étape : _____________________</p></section>
<details class="panel answers"><summary>Corrigé enseignant</summary><p>1 → C · 2 → B · 3 → A</p><p>Exemples de production :</p>{models}<p>D’autres phrases correctes du thème sont acceptées. Prononciation intelligible ; aucune note automatique.</p></details>
<section class="panel video"><h2>Ressources vidéo</h2>{videos}<details><summary>Candidates à revoir par l’enseignant</summary>{candidates or '<p>Aucune candidate enregistrée.</p>'}<p>Vérifier âge, débit, vocabulaire, segment utile et objectif. Aucun téléchargement, sous-titre ou transcript redistribué.</p></details></section>'''

VOICE='''function wireVoice(kit){const status=document.getElementById('voice-status');document.getElementById('speak').onclick=()=>{if(!('speechSynthesis' in window)){status.textContent='Lecture vocale non disponible : l’enseignant peut lire les modèles.';return;}const voice=window.speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith('fr'));if(!voice){status.textContent='Aucune voix française chargée. Vérifiez les voix du navigateur ou lisez les modèles.';return;}window.speechSynthesis.cancel();const utter=new SpeechSynthesisUtterance(kit.models.join(' '));utter.lang=voice.lang;utter.voice=voice;utter.rate=0.85;utter.onstart=()=>status.textContent='Lecture synthétique en cours : '+voice.name;utter.onend=()=>status.textContent='Lecture terminée. Prononciation à vérifier par l’enseignant.';utter.onerror=()=>status.textContent='La lecture a échoué. Utilisez la lecture de l’enseignant.';window.speechSynthesis.speak(utter);};document.getElementById('stop').onclick=()=>{if('speechSynthesis' in window)window.speechSynthesis.cancel();status.textContent='Lecture arrêtée.';};}'''

def js_json(value):return json.dumps(value,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')

def render_kit(kit):
 return '<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(kit['title'])+' | FLE Resource Studio</title><style>'+CSS+'</style></head><body><main><header><span class="eyebrow">JUNIOR BOOTO WABA · RESSOURCE A1</span><h1>FLE Resource Studio</h1></header>'+body(kit)+'<footer>Contenus originaux proposés avec assistance IA. Glossaire explicite FR/ES/EN. Usage à adapter, aucune donnée d’élève incluse.</footer></main><script>'+VOICE+'\nwireVoice('+js_json(kit)+');</script></body></html>'


def render_studio(catalog):
 variants={}
 for t in catalog['themes']:
  for support in SUPPORTS:
   for lang in ('fr','es','en'):
    kit=build_kit(catalog,t['id'],support=support,language=lang)
    variants[t['id']+'|'+support+'|'+lang]={'kit':kit,'html':body(kit)}
 options=''.join('<option value="'+t['id']+'">'+html.escape(t['title'])+'</option>' for t in catalog['themes'])
 controls='<div class="controls"><label>Thème<select id="theme">'+options+'</select></label><label>Niveau<select id="level"><option>A1</option></select></label><label>Appui<select id="support"><option value="model">Avec modèle</option><option value="guided">Appui renforcé</option><option value="independent">Autonomie</option></select></label><label>Aide de sens<select id="language"><option value="es">Espagnol</option><option value="en">Anglais</option><option value="fr">Français uniquement</option></select></label></div><div class="actions"><button id="download" class="primary">Exporter la fiche JSON</button><button id="print">Imprimer la fiche apprenant</button></div><p class="muted">L’objectif est fixé par le thème et reste commun aux trois aides. 5 thèmes · 50 entrées de glossaire · 45 combinaisons.</p>'
 script=VOICE+'\nconst variants='+js_json(variants)+''';let selected;function update(){if('speechSynthesis' in window)window.speechSynthesis.cancel();const key=document.getElementById('theme').value+'|'+document.getElementById('support').value+'|'+document.getElementById('language').value;selected=variants[key];document.getElementById('content').innerHTML=selected.html;wireVoice(selected.kit);}['theme','support','language'].forEach(id=>document.getElementById(id).addEventListener('change',update));document.getElementById('print').onclick=()=>window.print();document.getElementById('download').onclick=()=>{const blob=new Blob([JSON.stringify(selected.kit,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=selected.kit.theme+'-'+selected.kit.support+'-'+selected.kit.aid_language+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};update();'''
 return '<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FLE Resource Studio | Junior BOOTO Waba</title><style>'+CSS+'</style></head><body><main><header><span class="eyebrow">JUNIOR BOOTO WABA · FLE × PYTHON</span><h1>Une ressource.<br>Trois chemins pour apprendre.</h1><p>Choisir le thème, ajuster l’aide et préparer une fiche cohérente.</p></header>'+controls+'<div id="content"></div><noscript><p>JavaScript est nécessaire aux sélections ; les cinq fiches HTML individuelles sont disponibles dans le pack.</p></noscript><footer><p>Studio local : assemblage explicite de contenus originaux, pas une génération libre par IA. Le navigateur sélectionne des variantes préconstruites par Python. Traductions du glossaire ; pas d’API de traduction active. Lecture vocale dépendante du navigateur, sans fichier audio enregistré.</p><p>API Python locale fournie dans le pack. YouTube : métadonnées optionnelles, revue pédagogique distincte. Aucune donnée d’élève et aucune efficacité en classe revendiquée.</p><p lang="en">A reproducible A1 resource studio with five themes, an explicit trilingual glossary, three support pathways and observable success criteria. Teacher review required.</p></footer></main><script>'+script+'</script></body></html>'
